 function render(){return MISSY_EVIDENCE_A11Y.refresh('missy-export-dictionary',renderContent);}
 function renderContent(){
  const host=document.getElementById('loadedcard');if(!host)return;let box=document.getElementById('missy-export-dictionary');
  if(!box){box=document.createElement('details');box.id='missy-export-dictionary';box.setAttribute('data-i18n-skip','');box.addEventListener('toggle',render);host.append(box);}
  const title=document.createElement('summary');title.textContent=t('Evidence export field dictionary (read only)','证据导出字段字典（只读）');MISSY_EVIDENCE_A11Y.reset(box,title);if(!box.open)return;
  const doc=snapshot(),lang=UI_LANG==='zh'?'zh':'en';for(const value of [doc.boundary[lang],doc.header_rule[lang]]){const p=document.createElement('p');p.textContent=value;box.append(p);}
  const label=document.createElement('label');label.textContent=t('Export: ','导出：');const select=document.createElement('select');select.setAttribute('aria-label',t('Evidence export','证据导出'));doc.exports.forEach((e,i)=>{const option=document.createElement('option');option.value=String(i);option.textContent=e.filename;select.append(option);});select.value=String(selected);select.onchange=()=>{selected=Number(select.value);render();};label.append(select);box.append(label);
  const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');for(const name of [t('CSV field','CSV字段'),t('Meaning and limits','含义与界限')]){const th=document.createElement('th');th.scope='col';th.textContent=name;tr.append(th);}head.append(tr);table.append(head);const body=document.createElement('tbody');for(const field of doc.exports[selected].fields){const tr=document.createElement('tr');for(const text of [field.key,field.description[lang]]){const td=document.createElement('td');td.textContent=text;tr.append(td);}body.append(tr);}table.append(body);box.append(table);
  const button=document.createElement('button');button.type='button';button.textContent=t('Download field dictionary (JSON)','下载字段字典（JSON）');button.onclick=()=>download('evidence_export_dictionary.json',JSON.stringify(snapshot(),null,2),'application/json');box.append(button);
