function acquisitionStats(channels){
  if(!channels)return [];
  return Object.keys(channels).map(key=>{
    const cycles=Object.keys(channels[key]).map(Number).sort((a,b)=>a-b),lengths=uniq(cycles.map(c=>channels[key][c].length));
