    if (dv.getUint32(lho, true) !== 0x04034b50) throw new Error('Bad local header: ' + name);
    const start = lho + 30 + dv.getUint16(lho + 26, true) + dv.getUint16(lho + 28, true);
    if(start+csize>cdOffset)throw Error('ZIP payload bounds');
