  const groups=new Map();
  (raw||reviewEventsWithoutIntegrity()||[]).forEach((e,i)=>{
    const sev=FINDING_SEVERITY_RANK[e&&e.severity]!=null?e.severity:"review";
    const key=findingKey(Object.assign({},e,{severity:sev})),g=groups.get(key);
