function pdfStr(s){
  let o="";
  for(const ch of String(s==null?"":s)){
    const sp=PDF_SPELL[ch];
    if(sp!==undefined){o+=pdfStr(sp);continue;}
    const win=PDF_WINANSI[ch];
    const c=win!==undefined?win:ch.codePointAt(0);
    if(ch==="("||ch===")"||ch==="\\")o+="\\"+ch;
    else if(c===10)o+="\\n";
    else if(c<32)o+=" ";
