    if("iljI|!.,;:'`".includes(ch))u=222;
    else if("ftr()[]{}/\\-".includes(ch))u=333;
    else if(" ".includes(ch))u=278;
    else if("0123456789".includes(ch))u=556;
    else if("mwMW@".includes(ch))u=833;
    else if(c>=65&&c<=90)u=667;
    else if(c>=97&&c<=122)u=556;
